    QJsonObject suffix(DDLDepartment &dept,const TaskOccurrence &o){auto t=dept.task(o.taskId);t["due"]=o.due.toString(Qt::ISODate);t["remainingCount"]=dept.suffixRemaining(o.taskId,QDate::fromString(o.key,Qt::ISODate));return t;}
